import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
export const rawHash=s=>createHash('sha256').update(s).digest('hex');
export function projection(d){return {kind:'nautilus-tile-authoring-source',version:1,id:d.id,revision:d.contentRevision,originalSourceJSON:d.sourceJSON,floorProfile:{id:d.floorBinding.profile.id,version:1,floors:d.floorBinding.floors.map(({id,elevationM})=>({id,elevationM}))},finishCatalogue:{id:d.finishBinding.id,version:1,contentDigest:d.finishBinding.digest},tileBundle:d.tileBundle,stackConstraints:d.constraints,authoring:d.authoring};}
export function expected(T,d,c){return {workspaceRevision:d.contentRevision,workspaceDigest:T.tileLayoutToken(projection(d)),hostDocumentDigest:T.tileLayoutToken(d),hostAuthorityToken:c.hostAuthorityToken,authorityContextToken:c.authorityContextToken,contentDigest:T.tileLayoutToken(d.authoring.library),decorationDigest:T.tileLayoutToken(d.authoring.decorations),resourceSetDigest:T.tileLayoutToken(d.resourceRefs),floorProfileDigest:T.tileLayoutToken(d.floorBinding),stackConstraintsDigest:T.tileLayoutToken(d.constraints),tileLayoutDigest:T.tileLayoutToken(d.tileBundle.layout),tileCatalogueDigest:d.tileBundle.layout.catalogueDigest};}
export function fixture(T,M,A,F){
 const made=A.createRectangleDefinition(T,{identity:{id:'def.original',revision:1,recipeId:'recipe.original.1'},sourceIds:{prefix:'source.original',surfaceId:'top',gridId:'grid.original'},widthM:8,depthM:4,finishId:'skin.stone-flags'}),copy=A.createRectangleDefinition(T,{identity:{id:'def.copy',revision:1,recipeId:'recipe.copy.1'},base:made.definition}),revision=A.createRectangleDefinition(T,{identity:{id:'def.copy',revision:2,recipeId:'recipe.copy.2'},base:copy.definition,edits:{depthM:5}}),saved=A.sealTileContentRecord(T,{kind:'nautilus-tile-preset',version:1,id:'preset.copy',revision:1,body:{label:'Two independent copies',definition:copy.pin,defaultLayers:[],defaultMarks:[],requires:copy.definition.body.requires,notices:copy.definition.body.notices}});
 const sourceJSON=JSON.stringify(M.blankMap('C1 actual public fixture')),heights=[0,2.12,4.24,6.36,8.48,10.6,12.72,14.84,16.96,19.08,21.2,23.32,25.44,27.56,29.68],floorBinding={kind:'nautilus-tile-stack-floor-binding',version:1,id:'aft-native-fifteen-table',profile:{id:'aft-native-fifteen',version:1},sourceSha256:rawHash(sourceJSON),floors:heights.map((elevationM,i)=>({id:'F'+String(i).padStart(2,'0'),label:String(i+1),elevationM,source:i<3?{kind:'legacy-layer',layerIndex:i}:{kind:'authored-tile'}}))};
 const seed=structuredClone(made.definition.body.recipe);seed.id='recipe.unused.seed';const catalogue=T.createTileCatalogue([seed]),tileBundle=T.tileBundle({kind:'nautilus-tile-layout',version:1,id:'map.c1',revision:0,catalogueDigest:catalogue.digest,floors:floorBinding.floors.map(({id,elevationM})=>({id,elevationM})),instances:[],joins:[],relations:[],selection:{seed:17,policyVersion:1},extensions:{retainedOpaque:{important:true}}},catalogue);
 const document={kind:'nautilus-tile-workbench-document',version:3,id:'workspace.c1',sourceJSON,floorBinding,finishBinding:F.tileFinishBinding(),tileBundle,constraints:{kind:'nautilus-stack-constraints',version:1,floorProfileId:floorBinding.profile.id,minimumClearanceM:1.5,owners:[],managedRelations:[]},contentRevision:0,authoring:{kind:'nautilus-tile-authoring-module',version:1,library:{kind:'nautilus-tile-content',version:1,id:'library.c1',definitions:[],presets:[],artwork:[]},decorations:{kind:'nautilus-local-decorations',version:1,surfaces:[],chunks:[],groups:[]},ownerPins:[]},resourceRefs:[]};
 const token=name=>T.tileLayoutToken({fixture:name}),context={hostAuthorityToken:token('initial actual host read'),authorityContextToken:token('retained host context'),presentationProfileDigest:token('headless test profile; no renderer'),resourceLeaseSetDigest:token('actual empty leases'),allocationLedgerDigest:token('actual zero allocations'),availableProfiles:['public-v1-source-validation','owner-local-level-top-v1'],availableFinishIds:['skin.stone-flags'],resourceBindings:[],allocations:{declaredDecodedAllocationBytes:0,residentMarksAllViews:0,rootsAllViews:0,trianglesAllViews:0,cellsAllViews:0,ownedAppearanceMaterialsAllViews:0,contributorsPerBin:0,binReferencesAllViews:0,derivedBufferBytesAllViews:0,atlasPagesAllViews:0}};
 const placement=(id,x)=>({ownerId:id,originM:[x,0,0],floorBindings:{base:'F00'},transform:{quarterTurns:0,mirrorX:false},locked:false,anchorIds:copy.definition.body.recipe.anchors.map(a=>a.id),freshMarkIds:[],freshLayerIds:[],chunkId:'chunk.unused'});
 const operations=[{kind:'recipe.create',body:{definition:made.definition}},{kind:'recipe.clone',body:{base:made.pin,definition:copy.definition}},{kind:'recipe.revise',body:{base:copy.pin,definition:revision.definition}},{kind:'preset.save',body:{preset:saved.record}},{kind:'preset.place',body:{preset:saved.pin,placements:[placement('owner.one',0),placement('owner.two',20)],defaults:'empty'}},{kind:'placement.upgrade',body:{ownerIds:['owner.one'],from:copy.pin,to:revision.pin,anchorDecisions:[],newRecipeAnchorIds:[{ownerId:'owner.one',anchorIds:revision.definition.body.recipe.anchors.map(a=>a.id)}]}}];
 return {document,context,made,copy,revision,saved,operations,command:(d,c,ops,id='request.fixture')=>({kind:'nautilus-tile-authoring-command',version:1,requestId:id,expected:expected(T,d,c),operations:ops.map((o,i)=>({opId:'op.'+i,...structuredClone(o)})),budgetProfile:'authoring-reference-proposal-v1'})};
}
export function runWorkflow(T,M,A,F,{json=false}={}){
 const f=fixture(T,M,A,F);let document=f.document,serial=0,preparedCount=0,appliedCount=0,pendingTarget=null;const targets=[],plans=[],history=[structuredClone(document)];
 const consumer=T.createRetainedTileConsumer({read:()=>({bundle:document.tileBundle,token:f.context.hostAuthorityToken,contextToken:f.context.authorityContextToken}),compareAndSwap(packet){assert.equal(packet.requestId,pendingTarget.requestId);assert.equal(packet.expected.hostToken,f.context.hostAuthorityToken);assert.deepEqual(packet.nextBundle,pendingTarget.targetDocument.tileBundle);if(!packet.canCommit())return false;document=pendingTarget.targetDocument;appliedCount++;return true;}});
 try{for(let i=0;i<f.operations.length;i++){
 const before=document,command=f.command(document,f.context,[f.operations[i]],'request.'+i),input={document,command:json?JSON.stringify(command):command,context:f.context},plan=A.planTileAuthoring(T,input);assert.equal(plan.ok,true,JSON.stringify(plan));plans.push(plan);let prepared=null;if(plan.route==='public-v1-repair'){prepared=consumer.prepare(plan.request);preparedCount++;assert.equal(prepared.ok,true,JSON.stringify(prepared));}
 const target=A.bindTileAuthoringTarget(T,{before:document,plan,prepared});assert.equal(target.ok,true,JSON.stringify(target));assert.equal(target.committable,false);pendingTarget=target;
 if(i<4){assert.equal(plan.route,'source-unchanged');assert.deepEqual(target.targetDocument.tileBundle,before.tileBundle);assert.deepEqual(target.fingerprints.source,target.fingerprints.target);document=target.targetDocument;}else{assert.equal(plan.route,'public-v1-repair');const ack=consumer.apply(prepared);assert.equal(ack.committed,true);}
 assert.equal(document.contentRevision,i+1);f.context.hostAuthorityToken=T.tileLayoutToken({document,serial:++serial});targets.push(structuredClone(document));history.push(structuredClone(document));
 }
 assert.equal(preparedCount,2);assert.equal(appliedCount,2);assert.equal(document.tileBundle.layout.revision,2);assert.equal(document.tileBundle.recipes.length,3);assert.deepEqual(document.tileBundle.recipes.find(r=>r.id==='recipe.unused.seed'),f.document.tileBundle.recipes[0]);
 assert.deepEqual(targets[4].authoring.ownerPins.find(o=>o.ownerId==='owner.two'),document.authoring.ownerPins.find(o=>o.ownerId==='owner.two'));assert.deepEqual(targets[4].tileBundle.layout.instances.find(o=>o.id==='owner.two'),document.tileBundle.layout.instances.find(o=>o.id==='owner.two'));assert.equal(document.authoring.ownerPins.find(o=>o.ownerId==='owner.one').preset,null);assert.deepEqual(document.authoring.library.presets[0],f.saved.record);assert.deepEqual(JSON.parse(JSON.stringify(document)),document);
 return {document,targets,history,plans,preparedCount,appliedCount};
 }finally{consumer.dispose();}
}
